"""Render bounded diagnostics, including negative/inconclusive findings."""
from pathlib import Path
import json
import numpy as np
import pandas as pd
from .research import ROOT,OUT,CORE,BLOCKS

def md(frame,columns=None):
    if columns:frame=frame[columns]
    frame=frame.copy().fillna('no identificable')
    for c in frame:
        frame[c]=frame[c].map(lambda x:f'{x:.4f}' if isinstance(x,(float,np.floating)) else str(x))
    return '| '+' | '.join(frame.columns)+' |\n|'+'---|'*len(frame.columns)+'\n'+'\n'.join('| '+' | '.join(row)+' |' for row in frame.to_numpy())

def build(audit,variation,pairs,retro,within,cross,metrics,dominant):
    dim=pd.read_csv(OUT/'phase_i/dimensionality.csv');stability=pd.read_csv(OUT/'phase_i/subspace_stability.csv')
    selected=[c for cols in BLOCKS.values() for c in cols]
    primary=['S2_lai_promedio_runup_start_day','S2_savi_promedio_runup_duration','TOPO_BASIC_slope_mean','HIST_S2_ndvi_promedio_mean','HIST_S2_ndvi_promedio_std','geo250_composition_entropy','CLIMATE_dtr_mean_std','tmax_may_2025']
    cf=cross[cross.variable.isin(primary)&cross.subset.eq('all138')]
    assoc=retro[retro.variable.isin(primary)&retro.subset.eq('all138')]
    w=within[within.variable.isin(primary)&within.weighting.eq('equal_profile')]
    summaries=[]
    for c in selected:
        ww=within[within.variable.eq(c)&within.weighting.eq('equal_profile')].set_index('subset')
        rr=retro[retro.variable.eq(c)&retro.subset.eq('all138')].iloc[0]
        vv=audit[audit.variable.eq(c)].iloc[0]
        cc=cross[cross.variable.eq(c)&cross.subset.eq('all138')]
        loo=pd.read_csv(OUT/'phase_ii/leave_profile_out.csv');ll=loo[loo.variable.eq(c)].correlation.dropna()
        summaries.append(dict(variable=c,contrasting_profiles=vv.within_contrasting_profiles,linear_CT3_unexplained=vv.fraction_unexplained_by_linear_CT3,retrospective_partial=rr.partial_OLS_CT3,within_equal_all=ww.loc['all138','correlation'],within_equal_outside=ww.loc['outside_Chignahuapan','correlation'],within_equal_omit_dominant=ww.loc['omit_dominant_profiles','correlation'],leave_profile_min=ll.min(),leave_profile_max=ll.max(),cross_protocol_min=cc.mean_correlation.min(),cross_protocol_max=cc.mean_correlation.max(),interpretation='regional_only_if_no_within_contrast' if vv.within_contrasting_profiles==0 else 'observed_contrast; association not predictive increment'))
    ss=pd.DataFrame(summaries);ss.to_csv(OUT/'phase_ii/candidate_evidence_summary.csv',index=False)
    counts=dict(total=len(audit),numeric=int(audit.numeric.sum()),categorical=int((~audit.numeric).sum()),excluded_metadata=int(audit.fixed_covariate_status.ne('fixed_processed_covariate').sum()),constant_or_empty_138=int((audit.unique_138<=1).sum()),within_contrast_variables=int((audit.within_contrasting_profiles>0).sum()),zero_within_contrast_variables=int((audit.within_contrasting_profiles==0).sum()),equivalence_groups=int(audit.loc[audit.observed_equivalence_group.ne(''),'observed_equivalence_group'].nunique()),columns_in_exact_groups=int(audit.observed_equivalence_group.ne('').sum()),redundancy_relations=len(pairs))
    (OUT/'audit/summary_counts.json').write_text(json.dumps(counts,indent=2),encoding='utf-8')
    input_note='Se usan197 parcelas para describir X y138 para diagnóstico asociativo. Las59 sin etiqueta nunca deciden candidatas por Y ni reciben predicciones. Las representaciones sobre197 son descriptivas/transductivas, no transformaciones inductivas listas para reutilizar. No se ajustaron nuevos modelos predictivos de rendimiento, componentes supervisados, correctores ni modelos finales.'
    method_note='El porcentaje no explicado por C-T3 es residual de una proyección lineal de X sobre las cuatro entradas, no información condicional independiente. FWL retrospectivo utiliza OLS para ambos lados; C-T3 real es Elastic Net regularizado y sus errores OOF NO son residuos FWL. Las asociaciones cross-fitted aquí reutilizan errores OOF externos C-T3 y residualizan solo X con entrenamiento externo. No son estimación DML, no son efecto causal y no evalúan mejora de un predictor ampliado. No se generan residuos para entrenar un corrector. No hay p-valores ni intervalos inferenciales: perfiles/municipios escasos, pares y repeticiones dependientes.'
    conditioned=['# Fase II: asociación condicionada a C-T3','',input_note,'',method_note,'','## Bloques fijados antes del nuevo diagnóstico con Y','']
    for name,cols in BLOCKS.items():conditioned += [f'- {name}: '+', '.join(cols)]
    conditioned += ['', '## Asociaciones retrospectivas', '',md(assoc,['variable','n','n_profiles','raw_correlation','partial_OLS_CT3','between_profile_correlation']),'','## Asociaciones intraperfil controlando NDVI mayo','',md(w,['variable','subset','n','n_profiles','correlation','support_sufficient']),'', '## Errores OOF C-T3 versus variación X residualizada en entrenamiento','',md(cf,['variable','protocol','mean_correlation','min_correlation','max_correlation','n_repeats','min_n']),'','No usar el signo o tamaño para seleccionar automáticamente una variable. Temperatura y DTR pueden tener asociación regional sin distinguir parcelas dentro del perfil. En los análisis regionales/globales no se controla causalmente por municipio: se distinguen niveles por diagnóstico, no se aísla un mecanismo. Las omisiones y asociaciones con la muestra completa son retrospectivas.','', 'Las tablas same_model_pair_associations.csv conservan ambos pesos, solo parejas del mismo fold, sus parcelas y perfiles; muchas parejas no crean soporte independiente. El flag de20parcelas/3perfiles es una convención de lectura, no garantiza identificabilidad. Ausencia de correlación lineal no descarta relaciones no lineales.']
    (OUT/'report/conditioned_analysis.md').write_text('\n'.join(conditioned),encoding='utf-8')
    technical=['# Información incremental condicionada a C-T3: informe técnico','',input_note,'',f'Conteos auditados: {json.dumps(counts,ensure_ascii=False)}. Se verificaron197 IDs,138 etiquetas exactas y59 sin etiqueta;53 perfiles totales,43 etiquetados,12 repetidos/31singleton y107 parcelas en perfiles repetidos. Dos perfiles dominantes ({dominant}) concentran62 etiquetas locales.','', '## 1. Qué contiene C-T3','', 'Total de lluvia abril–octubre2025; fracción abril–junio/(total+1e-6); HHI mensual usando el mismo denominador; NDVI promedio válido de mayo2025. Modelo original Elastic Net: alpha0.001/0.01/0.1/1 y l1_ratio0.1/0.5/0.9, mediana/centrado/escala dentro de entrenamiento, piso de escala NDVI0.05, selección interna original por media de RMSE de folds. La referencia OOF no se modifica. Las65 particiones y grupos externos/internos se verifican. El período completo no es pronóstico disponible en mayo.','', '## 2. Qué variación no contiene','', 'El vector compacto no recupera generalmente las siete magnitudes mensuales; muchas series pueden compartir total/fracción/HHI. Tampoco contiene explícitamente dinámica LAI/SAVI, historia, pendiente ni cartografía. Eso no significa que omita información predictiva: puede ser redundante o insuficientemente medida. Dentro del mismo perfil de lluvia las tres entradas compactas son constantes, por lo que la diferenciación C-T3 depende de NDVI.','', '## 3. Qué señales son redundantes','', f'{counts["columns_in_exact_groups"]} columnas pertenecen a{counts["equivalence_groups"]} grupos de igualdad observada no constante sobre197 parcelas. Las relaciones casi afines se calculan solo con columnas numéricas completas sobre197 y |r|>=0.99999. La igualdad no certifica misma procedencia o significado ni redundancia fuera de esta muestra. Constantes/vacías no se consideran grupos informativos. No se eliminaron fuentes.','', '## 4. Qué contrastes intraperfil existen','', md(audit[audit.variable.isin(primary)],['variable','type','within_contrasting_profiles','within_contrast_parcels','fraction_unexplained_by_linear_CT3']),'', 'Binarias y categorías utilizan discordancia de clases entre parejas y conteo de perfiles mixtos; no códigos ordinales. Proporciones/composiciones conservan advertencias de suma, solapamiento y ceros: la proyección euclídea describe columnas, no una geometría composicional causal. Temporal max_month es posición de calendario, no magnitud física; no se prioriza como predictor continuo por esta auditoría.','', '## 5. Qué asociaciones adicionales aparecen','', md(ss[ss.variable.isin(primary)],['variable','retrospective_partial','within_equal_all','within_equal_outside','within_equal_omit_dominant','cross_protocol_min','cross_protocol_max']),'',method_note,'', '## 6. Dependencia de Chignahuapan y perfiles dominantes','', 'Las asociaciones se presentan dentro/fuera del municipio, excluyendo ambos perfiles dominantes y omitiendo cada uno de43perfiles. Chignahuapan aporta71 etiquetas pero sus perfiles repetidos locales son solo2; fuera hay más perfiles con menos parcelas. La proporción de error local no es proporción de error absoluto territorial. Cualquier señal que cambie de signo al omitir grupos queda no estable; las tablas conservan también resultados negativos/no identificables.','', '## 7. Señal regional versus parcelaria','', 'Las variables climáticas constantes dentro del perfil solo pueden variar entre perfiles. Una asociación global o un VIP alto no permite diferenciación parcelaria directa; pueden modificar la función entre perfiles. Suelo/geología y localidades también pueden identificar territorios; no se usa estado/municipio/coordenadas como entrada. Las asociaciones intraperfil controlan NDVI pero no aíslan manejo, variedad, fecha de siembra o medición del rendimiento.','', '## 8. Dimensionalidad y representaciones justificables','',md(dim[dim.scope.eq('138')],['block','original_columns','nonconstant_columns','rank','effective_rank','participation_rank','components_90','components_95']),'', 'SVD del bloque escalado, mediana para faltantes y retirada de constantes aprendidas sobre la población descrita. Rango numérico usa tolerancia relativa máquina×dimensión. Rango efectivo por entropía y participación reflejan dispersión espectral, no dimensiones predictivas. La estabilidad compara subespacios top5 mediante ángulos principales,12 remuestreos por perfiles; no son intervalos de confianza. Cada muestra reutiliza los197 o138 según el alcance descrito. Los espectros globales por columnas y por bloques muestran dependencia de ponderación. Ninguna componente se entrega como entrada predictiva.','', 'Con una señal LAI o pendiente no hace falta PCA/PLS. Historia NDVI2 ya tiene dos dimensiones: repetir compresión amplia carece de justificación automática. Representaciones condicionadas por bloques solo ameritan diseño si conservan contraste y asociaciones regionalmente robustas; H4 permanece sin evaluar.','', '## 9. Qué no repetir','', 'PLS1867 global; screening indiscriminado; objetivos B; interceptos de perfil C-H1; sensibilidad GPR ya ejecutada; adiciones directas F7-E completas; soil PCA/residuales de lluvia idénticos a K/L. La nueva pregunta es condicionar la información a compact4, no presentar como nuevo lo ya observado frente a otras bases. F8 sigue sin ejecutarse.','', '## 10. Información que falta recolectar','', 'Método de obtención del rendimiento, producción y superficie cosechada; fechas de siembra/cosecha, variedad, manejo/fertilización y disponibilidad real de agua; mediciones de suelo parcelario (profundidad, textura, materia orgánica, humedad) con unidades y muestreo; nuevas etiquetas en múltiples perfiles, municipios y campañas. Son hipótesis de medición a priorizar por costo y contraste local, no causas demostradas.','', '## Límites y estado de hipótesis','', 'H1 se respalda solo para variables con contraste observado. H2 es evidencia asociativa condicionada limitada y dependiente de modelo/nivel. H3 tiene diagnóstico espectral de posibilidad de compresión, no representación predictiva validada. H4 no se ejecutó y no se considera demostrada. Incluso una futura OOF honesta seguiría exploratoria por uso repetido de las mismas138etiquetas. No se prometen mejoras ni se declara Champion.','', '## Referencias metodológicas','', '- [PCA, documentación scikit-learn](https://scikit-learn.org/1.7/modules/generated/sklearn.decomposition.PCA.html): reducción de varianza de X, distinta de ganancia predictiva.', '- [Prevención de fuga, scikit-learn](https://scikit-learn.org/1.7/common_pitfalls.html): ajustes dentro del entrenamiento.', '- [Chernozhukov et al., double/debiased machine learning](https://arxiv.org/abs/1608.00060): motivación de separación/cross-fitting; este diagnóstico no implementa sus estimadores ni inferencia causal.']
    (OUT/'report/technical_report.md').write_text('\n'.join(technical),encoding='utf-8')
    proposal=pd.DataFrame([
       dict(experiment='P0',hypothesis='reference identity',signals='compact4',method='recover/replay frozen C-T3 only',control='archived C-T3',validation='65 original outer/inner',risk='reference drift',acceptance='exact predictions/targets',cost='0 new fits if recovered;65 replays',stop='identity mismatch',previous_evidence='C stage',new_information='implementation control only',refutation='reproduction discrepancy'),
       dict(experiment='P1',hypothesis='LAI timing complements compact4',signals='compact4 + LAI runup start',method='joint EN same12 grid; no PCA needed for1descriptor',control='P0 and optional original monthly F4-E2',validation='65 outer/inner; absolute and same-model pair both weights',risk='retrospective discovery and LAI interpretation',acceptance='proposed geographic RMSE gain>=.01 and no RMSE/MAE harm>.01 in other protocols; no pair harm>.01 both weights; omission stability',cost='3185 fits; estimate only, not benchmark',stop='no stable conditional support or geographic harm; do not expand grid',previous_evidence='F4-E small local gain',new_information='test incremental utility against compact4, not monthly base',refutation='no external gain or gain only dominant profiles'),
       dict(experiment='P2',hypothesis='small slope correction beyond compact4',signals='compact4 + slope',method='defer to existing F8 R0/R1 design, do not duplicate here',control='P0, joint alternative only after review',validation='strict nested cross-fitting per F8',risk='crossfit/refit mismatch and regional bias',acceptance='use F8 proposal gates; requires separate review',cost='F8 cached nested budget exists, not executed',stop='lambda0 or municipal/spatial harm',previous_evidence='J/K/F6/F7 localized slope and F8 audit',new_information='only if conditioned diagnostics support continuation',refutation='correction contributes no stable OOF improvement'),
       dict(experiment='P3_RESERVE',hypothesis='history preserves a distinct stable parcel contrast',signals='same NDVI2 only',method='no broad PLS/PCA; original2dimension representation first, conditioned representation design if warranted',control='P0 and matching base+single block',validation='fully nested and original65; no external winner selection',risk='history temporal definition, territorial confounding',acceptance='needs stable conditioned support before authorizing fits; same proposed margins',cost='not budgeted until support review; no automatic execution',stop='sign instability/dominant-profile dependence/territorial costs',previous_evidence='F6 local gains, F7 direct harms',new_information='conditional informativeness distinct from direct architecture',refutation='association unsupported or gain regional only'),
    ])
    proposal.to_csv(OUT/'report/proposed_experiments.csv',index=False)
    pr=['# Propuesta posterior, pendiente de revisión','', 'No se ejecutaron fasesIII–IV. No se recomienda una arquitectura por tener asociación parcial alta. La prioridad potencialLAI procede de evidencia previa y una pregunta distinta sobre compact4, no de elegir el máximo del nuevo diagnóstico. Si las asociaciones condicionadas no son estables, detener sin entrenar nuevas variantes. Pendiente no abre otra batería: referir aF8 existente. Historia permanece secundaria. Temperatura/suelo/geología no se convierten automáticamente en candidatos por VIP, varianza o separación.','',md(proposal),'', 'Los márgenes propuestos0.01t/ha son convenciones prácticas heredadas para revisión, no significación estadística ni beneficio económico demostrado. Añadir checks de sesgo por bloque/municipio y omisiones sin reajuste; ninguna ganancia solo aleatoria demuestra transferencia. No elegir regiones/modelos usando folds externos. Una nueva validación con campaña o municipios independientes sigue necesaria.','', 'Representación conjunta y corrector residual no son equivalentes. Si se autoriza la primera, repetir todo preprocesamiento/selección en cada entrenamiento interno. Si se autoriza un corrector, targets cross-fitted deben excluir cada etiqueta de ajuste y tuning; seleccionar amplitud incluyendo0 únicamente dentro del entrenamiento correspondiente. Las proyecciones/PCA descriptivas de esta entrega nunca se reutilizan como transformaciones predictivas.']
    (OUT/'report/next_phase_proposal.md').write_text('\n'.join(pr),encoding='utf-8')
    from matplotlib import pyplot as plt
    fig,axes=plt.subplots(1,2,figsize=(12,5))
    plot=ss[ss.variable.isin(primary)].set_index('variable')
    plot[['within_equal_all','within_equal_outside','within_equal_omit_dominant']].plot.barh(ax=axes[0]);axes[0].set(title='Asociación intraperfil controlando NDVI',xlabel='Correlación descriptiva')
    globals=dim[dim.block.str.startswith('ALL_') & dim.scope.eq('138')];axes[1].bar(globals.block,globals.effective_rank);axes[1].set(title='Rango efectivo:138 parcelas',ylabel='Entropía espectral');axes[1].tick_params(axis='x',rotation=20)
    fig.tight_layout();fig.savefig(OUT/'figures/diagnostic_summary.png',dpi=150);plt.close(fig)
    doc=ROOT/'documentation/ct3_incremental_information.md'
    if doc.exists():raise FileExistsError(doc)
    doc.write_text('# Información incremental condicionada a C-T3\n\nFases I–II diagnósticas; cero nuevos predictores de rendimiento/correctores, cero PRED.\n\n- [Auditoría por variable](../outputs/research/ct3_incremental_information/v1/phase_i/variable_audit.csv)\n- [Matriz de evidencia previa](../outputs/research/ct3_incremental_information/v1/audit/previous_evidence.csv)\n- [Análisis condicionado](../outputs/research/ct3_incremental_information/v1/report/conditioned_analysis.md)\n- [Informe técnico:10preguntas](../outputs/research/ct3_incremental_information/v1/report/technical_report.md)\n- [Propuesta posterior sin ejecución](../outputs/research/ct3_incremental_information/v1/report/next_phase_proposal.md)\n\nImplementación src/ct3_information; ejecución scripts/371_ct3_information.py; tests/test_ct3_information.py. Nueva ejecución requiere versión nueva.\n',encoding='utf-8')
